// Some portions generated by Codex
package org.eclipse.rdf4j.queryrender;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope;
import org.eclipse.rdf4j.query.impl.RemoteBNode;
import org.eclipse.rdf4j.queryrender.sparql.PrefixIndex;
import org.eclipse.rdf4j.queryrender.sparql.util.TermRenderer;
import org.junit.jupiter.api.Test;

class RemoteBlankNodeRenderingTest {

	@Test
	void importedAliasesCannotBeAdvertisedAsLocalReferences() {
		var vf = SimpleValueFactory.getInstance();
		var response = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), vf, new Object(), true);
		Value alias = response.map(vf.createBNode("canonical-remote"));
		for (Value value : List.of(alias,
				vf.createTripleTerm((Resource) alias, vf.createIRI("urn:p"), alias))) {
			IllegalArgumentException renderFailure = assertThrows(IllegalArgumentException.class,
					() -> RenderUtils.toSPARQL(value));
			assertTrue(renderFailure.getMessage().contains("blank-node identity"));

			IllegalArgumentException termFailure = assertThrows(IllegalArgumentException.class,
					() -> TermRenderer.convertValueToString(value, new PrefixIndex(Map.of()), false));
			assertTrue(termFailure.getMessage().contains("blank-node identity"));
		}
	}
}
